const { z } = require('zod');

const listQuery = z.object({
  // `?all=true` — admins list every user's grants instead of just their own.
  all: z.literal('true').optional(),
});

// Grant ids are generated by oidc-provider (URL-safe random strings).
const idParam = z.object({ id: z.string().regex(/^[A-Za-z0-9_-]{1,64}$/) });

module.exports = { listQuery, idParam };
